import {showDockingStructure,showCorrespondence,showPlatformDocking} from './structure-viewer.js';
import {helpButton} from './column-help.js';
import {pendingSubmission,acknowledgeSubmission} from './submission-state.js';
import {requestErrorText} from './api-request.js';
import {validateResearchSelection} from './research-selection.js';
import {identityLabel} from './research-inputs.js';
import {candidateName,candidateRole,priorityExplanationMarkup,topicalContributionMarkup,skinEvaluationMarkup,cachedToxicityMarkup,additionalToxicityMarkup} from './research-results.js';

const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=x=>x===null||x===undefined||x===''?'—':Number(x).toLocaleString('ko-KR',{maximumFractionDigits:2});
const percent=x=>typeof x==='number'&&Number.isFinite(x)?number(x*100)+'%':'—';
export function resourceCleanupWarning(resources){
 const holds=Array.isArray(resources?.quarantines)?resources.quarantines.filter(item=>item?.active===true):[];
 if(!holds.length&&resources?.resource_release_unverified!==true)return'';
 const globalHold=holds.some(item=>!item.physical_host),details=holds.map(item=>'<li>'+esc(item.worker||'서버 식별 확인 필요')+' · 작업 '+esc(item.job_id||'기록 확인 필요')+'</li>').join('');
 return'<section class="platform-panel" role="alert"><h2>작업 자원 정리 확인 필요</h2><p>종료를 확인하지 못한 작업이 있어 해당 서버의 새 계산을 보류합니다. GPU 여유 메모리나 예약 수만으로 자원 반환을 판단하지 않습니다. 이미 실행 중인 다른 연구는 유지합니다.</p>'+(globalHold?'<p>계산 서버를 식별할 수 없어 모든 새 계산을 보류합니다.</p>':'')+'<p>설치 담당자에게 아래 작업의 처리 기록을 전달하세요. 같은 실행 시도의 종료 확인을 받은 뒤에만 계산 차단을 해제합니다.</p>'+(details?'<ul>'+details+'</ul>':'')+'</section>';
}
export const initialDescending=key=>!['name','candidate_id','dock_affinity','primary_docking_score','mmgbsa_dG'].includes(key);
const state={snapshot:null,target:null,sort:'priority_score_v2',descending:true,offset:0,q:'',purchase_first:true,
 filters:{hide_critical:true,hide_opposing:true,hide_severe_admet:true,include_missing_topical:true,include_missing_pchembl:true,min_topical:0,min_pchembl:0},epoch:0};
const cols=[['name','화합물명'],['candidate_id','후보 ID'],['role','역할'],['priority_score_v2','실험 우선순위'],['discovery_score','탐색 점수'],['pchembl','pChEMBL'],['topical_score','피부 점수'],['dock_affinity','기존 도킹 원값'],['primary_docking_score','새 도킹 원값'],['purchasable','구매 정보']];
export function researchStudyLabel(run,snapshot={}){
 if(!run)return String(snapshot.provenance?.marker||snapshot.provenance?.target_id||'이름 미확인 연구');
 const descriptor=run.input_descriptor||run.target_descriptor||run.research_input||run.request?.input||{};
 const name=identityLabel(descriptor),modes={assessment:'입력 물질 평가',similarity:'유사 후보 탐색',scaffold_hopping:'다른 골격 탐색'},mode=modes[run.search_mode||run.request?.search_mode||snapshot.provenance?.search_mode||run.analysis_mode]||'후보 탐색';
 const time=run.created_at||run.submitted_at||snapshot.created_at,stamp=typeof time==='string'&&Number.isFinite(Date.parse(time))?'저장 '+new Date(time).toLocaleString('ko-KR',{timeZone:'Asia/Seoul',month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'}):'시각 미기록';
 return name+' · '+mode+' · '+stamp;
}
const labels={novel_scaffold:'새 골격',evidence:'근거 중심',exploration:'불확실성 탐색',backfill:'다양성 보충',counter_control:'방향 대조군'};
const post=(api,path,body)=>api(path,{method:'POST',body:JSON.stringify(body)});
export function platformErrorText(error){return error?.status===404&&error?.message==='Unknown candidate'?'후보를 찾을 수 없습니다. 스냅샷과 후보 ID를 확인해 주세요.':requestErrorText(error)}
const message=e=>`<p class="platform-error" role="alert">${esc(platformErrorText(e))}</p>`;
function safeLink(value){try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)&&!u.username&&!u.password?u.href:null}catch{return null}}
function download(name,raw,type='application/octet-stream'){const url=URL.createObjectURL(new Blob([raw],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function fromBase64(value){return Uint8Array.from(atob(value),c=>c.charCodeAt(0))}
async function toBase64(file){if(file.size>8*1024*1024)throw Error('실험 파일은 8 MiB 이하여야 합니다.');const data=new Uint8Array(await file.arrayBuffer());let result='';for(let i=0;i<data.length;i+=32768)result+=String.fromCharCode(...data.subarray(i,i+32768));return btoa(result)}
function listen(root,selector,type,fn){root.querySelector(selector)?.addEventListener(type,async event=>{try{await fn(event)}catch(e){let error=root.querySelector(':scope > .platform-errors')||root.closest('main')?.querySelector(':scope > .platform-errors')||root.querySelector('.platform-errors')||document.querySelector('.platform-errors');if(error)error.innerHTML=message(e);else throw e}})}
const summary=(title,description)=>`<div class="page-heading"><div><h1>${title}</h1><p>${description}</p></div></div>`;

export async function renderPlatform({main,api,route='research',screens=[],selection=null,namespace='legacy'}){
 if(state.namespace!==namespace){state.namespace=namespace;state.snapshot=null;state.target=null;state.offset=0;delete state.filters.primary_docking_protocol;}
 let explicitSelection=selection;
 const requested=sessionStorage.getItem('skinpipe-discovery-result');if(requested&&route==='research'&&!selection){try{const selected=JSON.parse(requested);state.snapshot=selected.snapshot;state.target=selected.target;state.offset=0}catch{}sessionStorage.removeItem('skinpipe-discovery-result')}
 const epoch=++state.epoch;
 main.innerHTML=summary(route==='research'?'연구 후보 비교':route==='experiments'?'실험 후보 정리':route==='catalog'?'전체 화합물 DB 검색':'실행·오류 확인','원자료와 계산 상태를 보존하고, 실험에 필요한 후보와 근거를 연결합니다.')+'<div class="platform-errors"></div><div id="platform-body" aria-live="polite">불러오는 중입니다…</div>';
 const body=main.querySelector('#platform-body');
 try{
  if(route==='experiments'){await experiments(body,api,epoch);return}
  if(route==='resources'){await resources(body,api,epoch);return}
  if(route==='catalog'){await catalog(body,api,epoch);return}
  const snapshots=(await api('/v2/snapshots?view=summary')).snapshots;
  if(epoch!==state.epoch)return;
  const valid=snapshots.filter(s=>s.status==='verified');
  const failed=snapshots.filter(s=>s.status!=='verified');
  let researchRuns=[];if(namespace==='generalized'){try{researchRuns=(await api('/v2/discovery-runs?view=status')).runs||[]}catch{}}
  if(epoch!==state.epoch)return;
  const runFor=s=>researchRuns.find(run=>run.snapshot_id===s.snapshot_id);
  if(explicitSelection){validateResearchSelection(snapshots,explicitSelection);state.snapshot=explicitSelection.snapshot;state.target=explicitSelection.target;state.offset=0;
   if(explicitSelection.protocol!==null&&explicitSelection.protocol!==undefined)state.filters.primary_docking_protocol=explicitSelection.protocol;
   else{delete state.filters.primary_docking_protocol;if(state.sort==='primary_docking_score')state.sort='priority_score_v2'}}
  const warnings=failed.length?`<section class="platform-panel platform-error" role="alert"><h2>조회할 수 없는 스냅샷 ${number(failed.length)}개</h2><p>파일 무결성 또는 조회 오류로 열지 못한 자료입니다. 오류를 해결한 뒤 후보 수를 확인하세요.</p><ul>${failed.map(s=>`<li>${esc(s.provenance?.marker||s.provenance?.target_id||s.snapshot_id)} · ${esc(s.status)} · ${esc(s.reason||s.error||'원인 기록 확인 필요')}</li>`).join('')}</ul></section>`:'';
  if(!screens.length)screens=valid.filter(s=>s.provenance?.screen_id).map(s=>({id:s.provenance.screen_id,display_name:s.provenance.marker,node:s.provenance.target_id}));
  if(!valid.length){body.innerHTML=warnings+(failed.length?'<p>저장 스냅샷이 있으나 현재 검증된 후보 조회는 보류 중입니다.</p>':'<p>통합 스냅샷이 아직 없습니다. 기존 후보 화합물 화면에서 저장 결과를 계속 확인할 수 있습니다.</p>');return}
  if(!valid.some(s=>s.snapshot_id===state.snapshot))state.snapshot=valid[0].snapshot_id;
  const choose=()=>{const s=valid.find(v=>v.snapshot_id===state.snapshot);state.target=explicitSelection?.target||s.provenance?.target_id||Object.keys(s.target_counts||{})[0];return s};
  let snapshot=choose();
  const protocols=s=>(s.provenance?.primary_docking_protocols||[]).filter(p=>p.target_id===state.target);
  const protocolOptions=s=>'<option value="">전체 조건 · 원값 비교 주의</option>'+protocols(s).map(p=>`<option value="${esc(p.protocol_id)}" ${state.filters.primary_docking_protocol===p.protocol_id?'selected':''}>${esc(p.engine)} · 시드 ${esc(p.seed)} · ${esc(p.protocol_id.slice(0,10))} · ${number(p.candidate_count)}개</option>`).join('');
  if(!protocols(snapshot).some(p=>p.protocol_id===state.filters.primary_docking_protocol)){delete state.filters.primary_docking_protocol;if(state.sort==='primary_docking_score')state.sort='priority_score_v2'}
  body.innerHTML=warnings+`<div class="platform-toolbar"><label>${namespace==='generalized'?'비교할 연구':'분석 스냅샷'}<select id="platform-snapshot">${valid.map(s=>`<option value="${esc(s.snapshot_id)}" ${s.snapshot_id===state.snapshot?'selected':''}>${namespace==='generalized'?esc(researchStudyLabel(runFor(s),s))+' · 저장 관측 '+number(s.candidate_count)+'개':esc(s.provenance?.marker||Object.keys(s.target_counts||{}).join(', '))+' · '+esc(s.provenance?.target_id||'')+' · '+number(s.candidate_count)+'개 · '+esc(s.provenance?.screen_id||s.snapshot_id.slice(-8))}</option>`).join('')}</select></label><label class="platform-search">전체 후보 검색<input id="platform-query" type="search" value="${esc(state.q)}" placeholder="화합물명, ID, CAS, 구조"></label><button class="button primary" id="platform-batch">96개 + 대조군 초안</button><button class="button" id="platform-plan">계산 단계 보기</button></div>
   <div id="platform-study-context" class="research-study-context"></div><p id="platform-query-status" role="status" aria-live="polite"></p>
   <div class="platform-filters"><label><input type="checkbox" data-filter="hide_critical" ${state.filters.hide_critical?'checked':''}> critical 경고 숨김</label><label title="예측 위험 기준과 모델 버전은 후보 상세에서 확인합니다. 미평가를 안전으로 판정하지 않습니다."><input type="checkbox" data-filter="hide_severe_admet" ${state.filters.hide_severe_admet?'checked':''}> 강한 독성·피부독성 예측 숨김</label><label><input type="checkbox" data-filter="hide_opposing" ${state.filters.hide_opposing?'checked':''}> 반대 방향 대조군 숨김</label><label><input type="checkbox" id="platform-purchase" ${state.purchase_first?'checked':''}> 구매 정보 있는 후보 우선</label><label><input type="checkbox" data-filter="purchasable_only" ${state.filters.purchasable_only?'checked':''}> 구매 후보만</label><label><input type="checkbox" data-filter="measured_only" ${state.filters.measured_only?'checked':''}> 실측 근거만</label><label>피부 최소 <input type="number" min="0" max="10" step="0.1" data-filter="min_topical" value="${state.filters.min_topical}"></label><label>pChEMBL 최소 <input type="number" min="0" max="14" step="0.1" data-filter="min_pchembl" value="${state.filters.min_pchembl}"></label><label><input type="checkbox" data-filter="include_missing_topical" ${state.filters.include_missing_topical?'checked':''}> 피부 미평가 포함</label><label><input type="checkbox" data-filter="include_missing_pchembl" ${state.filters.include_missing_pchembl?'checked':''}> 활성 미측정 포함</label><label>새 도킹 비교 조건<select id="platform-protocol">${protocolOptions(snapshot)}</select></label><button class="text-button" id="platform-clear">제외 필터 해제</button></div>
   <p class="platform-note">우선순위는 실측 표적 근거 40% · 구조 근거 30% · 탐색 점수 30%의 휴리스틱입니다. 결측은 중립값으로 계산합니다. 후보별 근거 충족률도 함께 확인하세요. 열을 클릭하면 전체 저장 후보에서 다시 정렬합니다. 새 도킹 원값은 비교 조건을 선택해야 정렬할 수 있습니다.</p><div id="platform-counts"></div><div id="platform-table"></div><div class="platform-pagination"><button class="button" id="platform-prev">이전 50개</button><span id="platform-page"></span><button class="button" id="platform-next">다음 50개</button><button class="button" id="platform-csv">현재 상위 목록 CSV</button></div><div id="platform-extra"></div>`;
  function studyContext(){const run=runFor(snapshot);body.querySelector('#platform-study-context').innerHTML=namespace==='generalized'?`<strong>${esc(researchStudyLabel(run,snapshot))}</strong>${run?`<a class="button" href="#discovery?run=${encodeURIComponent(run.run_id)}">이 연구 결과·Excel 열기 →</a>`:''}<p>표에는 출발 물질·탐색 후보·참조 물질의 저장 관측이 함께 포함될 수 있습니다. 새로운 후보 수는 연구 결과에서 구분해 확인하세요. Excel은 전체 저장 관측과 개별 물질 탭을 포함합니다.</p><details><summary>연구 식별자와 원자료 연결</summary><p>${esc(snapshot.snapshot_id)} · ${esc(state.target)}</p></details>`:''}
  let queryEpoch=0,last;
  const query=async()=>{
   const own=++queryEpoch;
   studyContext();body.querySelector('#platform-query-status').textContent='선택한 연구와 조건으로 후보를 확인하고 있습니다…';body.querySelector('#platform-table').setAttribute('aria-busy','true');
   let result;try{result=await post(api,'/v2/candidate-queries',{snapshot_id:state.snapshot,target_id:state.target,q:state.q,filters:state.filters,sort:state.sort,descending:state.descending,purchase_first:state.purchase_first,limit:1000,page_size:50,offset:state.offset})}catch(error){if(epoch===state.epoch&&own===queryEpoch){body.querySelector('#platform-query-status').textContent='후보를 조회하지 못했습니다. 오류와 연결 상태를 확인해 주세요.';body.querySelector('#platform-table').setAttribute('aria-busy','false');body.querySelector('#platform-table').innerHTML='';body.querySelector('#platform-counts').innerHTML=''}throw error}
   if(epoch!==state.epoch||own!==queryEpoch)return;
   main.querySelector(':scope > .platform-errors').innerHTML='';last=result;const c=result.counts;body.querySelector('#platform-table').setAttribute('aria-busy','false');body.querySelector('#platform-query-status').textContent='조회 완료 · 조건 통과 '+number(c.filtered)+'개 · 현재 표시 '+number(result.rows.length)+'개';
   body.querySelector('#platform-counts').innerHTML=`<div class="platform-metrics">${[[namespace==='generalized'?'전체 저장 관측':'전체 모집단',c.population],['필터 적용 후',c.filtered],['상위 표시',c.displayed],['계산 기록 보유',c.population_calculated]].map(([k,v])=>`<div><small>${k}</small><strong>${number(v)}</strong></div>`).join('')}</div><p class="muted">critical ${number(c.reasons.critical)} · 방향 반대 ${number(c.reasons.opposing)} · 구매 정보 미확인 ${number(c.missing.purchase)} · 활성값 없음 ${number(c.missing.pchembl)}. 사유는 서로 중복될 수 있습니다.</p>`;
   body.querySelector('#platform-table').innerHTML=`<div class="table-wrap"><table class="platform-table"><thead><tr>${cols.map(([key,label])=>key==='role'?'<th>역할</th>':`<th aria-sort="${state.sort===key?(state.descending?'descending':'ascending'):'none'}"><span class="column-heading"><button data-sort="${key}" ${key==='primary_docking_score'&&!state.filters.primary_docking_protocol?'disabled':''} aria-label="${label} 정렬">${label} ${state.sort===key?(state.descending?'↓':'↑'):''}</button>${helpButton(key,label)}</span></th>`).join('')}<th><span class="column-heading">근거 충족 / 불확실성 ${helpButton('priority_evidence')}</span></th><th><span class="column-heading">계산 상태 ${helpButton('computation_status')}</span></th><th><span class="column-heading">상세 ${helpButton('detail')}</span></th></tr></thead><tbody>${result.rows.map((r,i)=>`<tr>${cols.map(([key])=>`<td>${key==='name'?esc(candidateName(r,state.offset+i)):key==='candidate_id'?esc(r.candidate_id):key==='role'?esc(candidateRole(r)):key==='priority_score_v2'?number(r[key])+priorityExplanationMarkup(r):key==='topical_score'?number(r[key])+topicalContributionMarkup(r):key==='primary_docking_score'?number(r.primary_docking?.score):key==='purchasable'?(r.purchasable===true?'구매 기록 있음':r.purchasable===false?'판매 미확인':'미평가'):number(r[key])}</td>`).join('')}<td>${percent(r.priority_coverage)} / ${number(r.priority_uncertainty)}</td><td>${esc(r.computation_status||r.states?.compute?.status||'기록 확인 필요')}</td><td><button class="text-button" data-detail="${i}">근거 보기</button></td></tr>`).join('')||'<tr><td colspan="13">조건에 맞는 후보가 없습니다. 필터를 해제하면 저장 후보를 다시 볼 수 있습니다.</td></tr>'}</tbody></table></div>`;
   body.querySelector('#platform-page').textContent=`${c.displayed?state.offset+1:0}–${state.offset+result.rows.length} / ${number(c.displayed)}`;
   body.querySelector('#platform-prev').disabled=state.offset===0;body.querySelector('#platform-next').disabled=result.next_offset===null;
   for(const b of body.querySelectorAll('[data-sort]'))b.onclick=()=>{state.descending=state.sort===b.dataset.sort?!state.descending:initialDescending(b.dataset.sort);state.sort=b.dataset.sort;state.purchase_first=false;body.querySelector('#platform-purchase').checked=false;state.offset=0;query().catch(e=>main.querySelector('.platform-errors').innerHTML=message(e))};
   for(const b of body.querySelectorAll('[data-detail]'))b.onclick=()=>candidateDetail(result.rows[Number(b.dataset.detail)],api,{snapshot:result.snapshot_id,target:result.target_id}).catch(e=>main.querySelector('.platform-errors').innerHTML=message(e));
  };
  listen(body,'#platform-snapshot','change',async e=>{explicitSelection=null;state.snapshot=e.target.value;snapshot=choose();delete state.filters.primary_docking_protocol;if(state.sort==='primary_docking_score')state.sort='priority_score_v2';body.querySelector('#platform-protocol').innerHTML=protocolOptions(snapshot);state.offset=0;await query()});
  listen(body,'#platform-protocol','change',async e=>{if(e.target.value)state.filters.primary_docking_protocol=e.target.value;else{delete state.filters.primary_docking_protocol;if(state.sort==='primary_docking_score')state.sort='priority_score_v2'}state.offset=0;await query()});
  let timer;listen(body,'#platform-query','input',e=>{state.q=e.target.value;clearTimeout(timer);timer=setTimeout(()=>{state.offset=0;query().catch(e=>main.querySelector('.platform-errors').innerHTML=message(e))},300)});
  for(const input of body.querySelectorAll('[data-filter]'))input.onchange=()=>{state.filters[input.dataset.filter]=input.type==='checkbox'?input.checked:Number(input.value);state.offset=0;query().catch(e=>main.querySelector('.platform-errors').innerHTML=message(e))};
  listen(body,'#platform-purchase','change',async e=>{state.purchase_first=e.target.checked;state.offset=0;await query()});
  listen(body,'#platform-clear','click',async()=>{state.filters={hide_critical:false,hide_opposing:false,hide_severe_admet:false,include_missing_topical:true,include_missing_pchembl:true,min_topical:0,min_pchembl:0};await renderPlatform({main,api,route,screens,namespace,selection:explicitSelection})});
  listen(body,'#platform-prev','click',async()=>{state.offset=Math.max(0,state.offset-50);await query()});
  listen(body,'#platform-next','click',async()=>{if(last?.next_offset!==null)state.offset=last.next_offset;await query()});
  listen(body,'#platform-batch','click',async e=>{e.target.disabled=true;try{const batch=await post(api,'/v2/experiment-batches',{snapshot_id:state.snapshot,target_id:state.target});await showBatch(body.querySelector('#platform-extra'),batch,api);body.querySelector('#platform-extra').scrollIntoView({block:'start',behavior:'smooth'})}finally{e.target.disabled=false}});
  listen(body,'#platform-plan','click',async()=>{const panel=body.querySelector('#platform-extra');await campaignPanel(panel,api,{snapshot_id:state.snapshot,target_id:state.target});panel.scrollIntoView({block:'start',behavior:'smooth'})});
  listen(body,'#platform-csv','click',async e=>{e.target.disabled=true;try{const frozenQuery=structuredClone({snapshot_id:state.snapshot,target_id:state.target,q:state.q,filters:state.filters,sort:state.sort,descending:state.descending,purchase_first:state.purchase_first,limit:1000,page_size:50});const rows=[];let offset=0;do{const page=await post(api,'/v2/candidate-queries',{...frozenQuery,offset});rows.push(...page.rows);offset=page.next_offset}while(offset!==null);const fields=['candidate_id','name','role','control_kind','redock_reference','priority_score_observed_channels','priority_imputed_weight','priority_score_status','target_id','smiles','priority_score_v2','discovery_score','pchembl','topical_score','dock_affinity','primary_docking_score','primary_docking_protocol','primary_docking_engine','purchasable','priority_coverage','priority_uncertainty'];const cell=x=>{let s=x===null||x===undefined?'':String(x);if(/^[=+\-@\t\r]/.test(s)&&typeof x!=='number')s="'"+s;return '"'+s.replaceAll('"','""')+'"'};download('SkinPipe_top1000.csv','\uFEFF'+[fields,...rows.map(r=>fields.map(k=>k==='primary_docking_score'?r.primary_docking?.score:k==='primary_docking_protocol'?r.primary_docking?.protocol_id:k==='primary_docking_engine'?r.primary_docking?.engine:r[k]))].map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8')}finally{e.target.disabled=false}});
  if(screens.length){const box=document.createElement('details');box.className='platform-panel';box.innerHTML=`<summary>기존 저장 분석을 연구 후보 비교에 동기화</summary><p>원본은 보존하고 화면·후보 ID와 파일 해시를 검증해 새 스냅샷을 만듭니다.</p><div class="platform-toolbar"><label>기존 분석<select id="platform-legacy-screen">${screens.map(s=>`<option value="${esc(s.id)}">${esc(s.display_name||s.marker)} · ${esc(s.node)} · ${esc(s.id)}</option>`).join('')}</select></label><button class="button" id="platform-legacy-import">원본 검증 후 동기화</button></div><div id="platform-legacy-progress"></div><div class="platform-errors"></div>`;body.append(box);listen(box,'#platform-legacy-import','click',async e=>{e.target.disabled=true;try{let result=await post(api,'/v2/legacy-imports',{screen_id:box.querySelector('#platform-legacy-screen').value});while(result.status==='running'&&epoch===state.epoch){box.querySelector('#platform-legacy-progress').textContent='원본과 후보를 검증하고 있습니다…';await new Promise(resolve=>setTimeout(resolve,1500));result=await api('/v2/legacy-imports/'+encodeURIComponent(result.import_id))}if(epoch!==state.epoch)return;if(result.status!=='complete')throw Error(result.error||'동기화가 완료되지 않았습니다.');state.snapshot=result.snapshot.snapshot_id;state.offset=0;await renderPlatform({main,api,route,screens,namespace})}finally{e.target.disabled=false}})}
  await query();
 }catch(e){if(epoch===state.epoch)body.innerHTML=message(e)+'<p>기존 저장 결과는 <a href="#candidates">후보 화합물</a>에서 확인할 수 있습니다.</p>'}
}

async function candidateDetail(row,api,context){
 const d=await api(`/v2/candidates/${encodeURIComponent(row.candidate_id)}?snapshot_id=${encodeURIComponent(context.snapshot)}&target_id=${encodeURIComponent(context.target)}`);
 if(!d||typeof d!=='object')throw Error('후보를 찾을 수 없습니다. 스냅샷과 후보 ID를 확인해 주세요.');
 const dialog=document.querySelector('#detail-dialog'),content=document.querySelector('#detail-content');
 d.docking=Array.isArray(d.docking)?d.docking:d.docking?[d.docking]:[];
 const offers=[...(d.offers||[]),...(d.supplier_offers||[]),...(d.catalog_sources||[]).flatMap(s=>s.offers||[])].map(o=>{const url=safeLink(o.product_url||o.purchase_route||o.url||o.source_url);return `<li>${esc(o.vendor||o.supplier||o.source||'공급사')} · 확인 ${esc(o.checked_at||o.retrieved_at||o.evidence_date||'날짜 미기록')} ${url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">구매처 홈페이지 열기 ↗</a>`:''}</li>`}).join('');
 content.innerHTML=`<div class="platform-detail"><button class="icon-button" id="platform-close" aria-label="상세 닫기">×</button><h2 id="detail-title">${esc(candidateName(d))}</h2><p class="research-smiles">확인한 분자 구조 (SMILES): ${esc(d.smiles||'구조 미기록')}</p><p>${esc(d.candidate_id)} · ${esc(d.target_id)} · 역할: ${esc(candidateRole(d))}</p><div class="platform-metrics"><div><small>실험 우선순위</small><strong>${number(d.priority_score_v2)}</strong>${priorityExplanationMarkup(d)}</div><div><small>근거 충족률</small><strong>${percent(d.priority_coverage)}</strong></div></div><p>원자료의 미측정값은 미측정으로 유지합니다. 비교 조건이 없는 과거 도킹·활성값은 우선순위 채널에 합산하지 않습니다.</p>${topicalContributionMarkup(d)}${skinEvaluationMarkup(d,d.structural_admet||{})}${cachedToxicityMarkup(d.admet,{candidateId:d.candidate_id||''})}${additionalToxicityMarkup(d.additional_toxicity,{candidateId:d.candidate_id||''})}<h3>구매 근거</h3><ul>${offers||'<li>출처와 확인 날짜가 있는 공급사 정보 미기록</li>'}</ul><details class="research-options"><summary>3D 구조·공통 구조 비교 (고급)</summary><p>저장된 좌표·정확한 참조 구조가 있는 기능만 사용할 수 있습니다. 비활성 버튼은 현재 자료가 부족한 기능입니다.</p><button class="button" id="platform-docking" ${!d.legacy_docking_url?'disabled':''}>저장 도킹 · MolStar</button><button class="button" id="platform-v2-docking" ${!(d.docking||[]).some(r=>r.artifact_valid&&r.pose_sha256)?'disabled':''}>새 계산 포즈 · MolStar</button><h3>스카폴드 대응</h3><button class="button" id="platform-stored-alignment" ${d.reference_alignment?.status==='complete'?'':'disabled'}>저장 참조 대응 · MolStar</button><label>비교할 기준 화합물 SMILES<input id="platform-reference" class="platform-reference" value="${esc(d.parent_smiles||'')}" placeholder="표적의 기준 구조를 입력하세요"></label><button class="button" id="platform-correspondence">공통 원자·3D 특징 보기</button></details><div class="platform-errors"></div><details><summary>실측·예측·출처 전체 기록</summary><pre>${esc(JSON.stringify(d,null,2))}</pre></details></div>`;
 content.querySelector('#platform-close').onclick=()=>dialog.close();
 listen(content,'#platform-docking','click',async()=>{const m=await api(d.legacy_docking_url);showDockingStructure({title:d.name||d.candidate_id,node:d.target_id,manifest:m,api})});
 listen(content,'#platform-v2-docking','click',async()=>showPlatformDocking({title:d.name||d.candidate_id,candidate:d,api,context}));
 listen(content,'#platform-stored-alignment','click',async e=>{e.target.disabled=true;try{const result=await api(`/v2/candidates/${encodeURIComponent(d.candidate_id)}/alignment?snapshot_id=${encodeURIComponent(context.snapshot)}&target_id=${encodeURIComponent(context.target)}`);await showCorrespondence({title:d.name||d.candidate_id,result})}finally{e.target.disabled=false}});
 listen(content,'#platform-correspondence','click',async e=>{e.target.disabled=true;try{const result=await post(api,'/v2/correspondence',{reference_smiles:content.querySelector('#platform-reference').value,candidate_smiles:d.smiles});await showCorrespondence({title:d.name||d.candidate_id,result})}finally{e.target.disabled=false}});
 if(!dialog.open)dialog.showModal();
}

async function experiments(body,api,epoch){const result=await api('/v2/experiment-batches');if(epoch!==state.epoch)return;body.innerHTML=`<p class="platform-note">표적별 고유 후보 최대 96개와 대조군을 별도로 보관합니다. 고정한 배치는 순서·구조·점수·정책을 변경할 수 없습니다.</p><div class="platform-toolbar"><label>실험 배치<select id="platform-batches"><option value="">배치를 선택하세요</option>${result.batches.map(b=>`<option value="${esc(b.batch_id)}">${esc(b.target_id)} · 후보 ${b.candidates.length} + 대조군 ${b.controls.length} · ${b.status==='frozen'?'고정됨':'초안'} · ${esc(b.created_at?.slice(0,10))}</option>`).join('')}</select></label><a class="button primary" href="#research">후보에서 새 배치 만들기</a></div><div id="platform-batch-detail"></div>`;listen(body,'#platform-batches','change',async e=>{if(e.target.value)await showBatch(body.querySelector('#platform-batch-detail'),await api('/v2/experiment-batches/'+encodeURIComponent(e.target.value)),api)})}

async function showBatch(root,batch,api){
 const frozen=batch.status==='frozen',selection=batch.policy.selection_report||{};
 root.innerHTML=`<section class="platform-panel"><h2>${esc(batch.target_id)} · 후보 ${batch.candidates.length}개 + 대조군 ${batch.controls.length}개</h2><p>${frozen?'고정된 실험 배치':'실험 배치 초안'} · ${esc(batch.batch_id)}</p><p>새 골격 부족 ${number(selection.category_deficits?.novel_scaffold)} · 다양성 보충 ${number(selection.backfill_count)} · 전체 미충족 ${number(selection.unfilled_count)}. 참조군 ${esc(selection.policy?.reference_status||'기록 확인 필요')}.</p><div class="platform-toolbar"><button class="button primary" id="platform-freeze" ${frozen?'disabled':''}>후보·순서·정책 고정</button><button class="button" id="platform-export" ${frozen?'':'disabled'}>CSV / XLSX / SDF / 근거 ZIP</button><label class="button">실험 CSV/XLSX 불러오기<input id="platform-results-file" type="file" accept=".csv,.xlsx" ${frozen?'':'disabled'}></label><button class="button" id="platform-observations">등록한 실측값</button><button class="button" id="platform-feedback" ${frozen?'':'disabled'}>다음 추천에 실측 근거 반영</button></div><div class="platform-errors"></div><div class="table-wrap"><table class="platform-table"><thead><tr><th>순서</th><th>구분</th><th>후보 ID</th><th>이름</th><th>선정 이유</th>${frozen?'':'<th>초안 편집</th>'}</tr></thead><tbody>${[...batch.candidates.map(r=>({...r,_role:'후보'})),...batch.controls.map(r=>({...r,_role:'대조군'}))].map((r,i)=>`<tr><td>${i+1}</td><td>${r._role}</td><td>${esc(r.candidate_id)}</td><td>${esc(r.name||'이름 미기록')}</td><td>${esc(labels[r.selection_lane]||r.selection_reason||r.role||'기록 확인 필요')}</td>${frozen?'':`<td><button class="text-button" data-edit="up" data-index="${i}" aria-label="위로">↑</button><button class="text-button" data-edit="down" data-index="${i}" aria-label="아래로">↓</button><button class="text-button" data-edit="remove" data-index="${i}">제거</button></td>`}</tr>`).join('')}</tbody></table></div><div id="platform-import-preview"></div><details><summary>고정 정책과 선정 근거</summary><pre>${esc(JSON.stringify(batch.policy,null,2))}</pre></details></section>`;
 for(const button of root.querySelectorAll('[data-edit]'))button.onclick=async()=>{try{const index=Number(button.dataset.index),isControl=index>=batch.candidates.length,rows=[...(isControl?batch.controls:batch.candidates)],local=isControl?index-batch.candidates.length:index;const action=button.dataset.edit;if(action==='remove')rows.splice(local,1);else{const other=local+(action==='up'?-1:1);if(other<0||other>=rows.length)return;[rows[local],rows[other]]=[rows[other],rows[local]]}button.disabled=true;const next=await post(api,`/v2/experiment-batches/${batch.batch_id}/update`,{candidate_ids:(isControl?batch.candidates:rows).map(r=>r.candidate_id),control_ids:(isControl?rows:batch.controls).map(r=>r.candidate_id)});await showBatch(root,next,api)}catch(e){root.querySelector('.platform-errors').innerHTML=message(e)}};
 listen(root,'#platform-feedback','click',async()=>{const preview=root.querySelector('#platform-import-preview');preview.innerHTML=`<h3>실측 근거를 새 추천 스냅샷에 반영</h3><p>기존 배치와 스냅샷은 그대로 보존합니다. 시험 조건을 검토하면 비교 가능한 측정값만 점수에 반영하고, 조건이 없으면 실측 근거만 추가합니다.</p><label>검토한 시험 조건 JSON (선택)<textarea id="platform-assay-contexts" rows="5" placeholder='{"assay-1":{"species":"Homo sapiens","assay_type":"biochemical","action":"inhibit","higher_is_better":false,"reviewed":true}}'>{}</textarea></label><button class="button primary" id="platform-apply-feedback">새 스냅샷 만들기</button><div class="platform-errors"></div>`;listen(preview,'#platform-apply-feedback','click',async e=>{e.target.disabled=true;try{const result=await post(api,'/v2/feedback-snapshots',{snapshot_id:batch.snapshot_id,target_id:batch.target_id,batch_ids:[batch.batch_id],assay_contexts:JSON.parse(preview.querySelector('#platform-assay-contexts').value)});state.snapshot=result.snapshot_id;state.target=batch.target_id;preview.innerHTML=`<p>실측 근거 스냅샷 생성: ${esc(result.snapshot_id)}</p><a class="button primary" href="#research">새 추천 확인</a>`}catch(error){e.target.disabled=false;throw error}})});
 listen(root,'#platform-freeze','click',async()=>showBatch(root,await post(api,`/v2/experiment-batches/${batch.batch_id}/freeze`,{}),api));
 listen(root,'#platform-export','click',async()=>{const result=await api(`/v2/experiment-batches/${batch.batch_id}/export`);const preview=root.querySelector('#platform-import-preview');preview.innerHTML='<h3>인계 파일 저장</h3>';for(const f of result.files){const b=document.createElement('button');b.className='button';b.textContent=f.name;b.onclick=()=>download(f.name,fromBase64(f.base64));preview.append(b)}});
 listen(root,'#platform-results-file','change',async e=>{const file=e.target.files[0];if(!file)return;const result=await post(api,'/v2/result-imports',{batch_id:batch.batch_id,filename:file.name,base64:await toBase64(file)});const preview=root.querySelector('#platform-import-preview');preview.innerHTML=`<h3>실험 결과 등록 전 검토</h3><pre>${esc(JSON.stringify(result,null,2))}</pre><button class="button primary" id="platform-confirm-import" ${(result.errors||[]).length?'disabled':''}>검토한 관측값 등록</button>`;listen(root,'#platform-confirm-import','click',async ev=>{ev.target.disabled=true;try{const pending=pendingSubmission(sessionStorage,'skinpipe-result-confirm-'+result.preview_id,{preview_id:result.preview_id});const done=await post(api,`/v2/result-imports/${result.preview_id}/confirm`,{idempotency_key:pending.id});acknowledgeSubmission(sessionStorage,'skinpipe-result-confirm-'+result.preview_id,pending.id);preview.innerHTML='<h3>등록 결과</h3><pre>'+esc(JSON.stringify(done,null,2))+'</pre>'}catch(e){ev.target.disabled=false;throw e}})});
 listen(root,'#platform-observations','click',async()=>{const observations=await api(`/v2/experiment-batches/${batch.batch_id}/observations`);root.querySelector('#platform-import-preview').innerHTML='<h3>등록된 실측 근거</h3><pre>'+esc(JSON.stringify(observations,null,2))+'</pre>'});
}

async function resources(body,api,epoch){const [resources,result,campaignList,optional]=await Promise.all([api('/v2/resources'),api('/v2/jobs'),api('/v2/campaigns'),api('/v2/optional-scorers')]);if(epoch!==state.epoch)return;body.innerHTML=`${resourceCleanupWarning(resources)}<p class="platform-note">GPU 대기와 계산을 구분합니다. 예산 차감에는 연결 단절 중 확인할 수 없는 실행 시간의 보수적 추정이 포함됩니다. 실제 엔진 측정값은 작업 이력과 원 결과에 따로 기록합니다. 예산 초과 후보는 보류합니다.</p><div class="platform-resource-grid">${resources.nodes.map(n=>`<section class="platform-panel"><h2>${esc(n.id)}</h2><p>${n.fresh?'최근 상태 수신':'상태 갱신 필요'}</p>${(n.telemetry.gpus||[]).map(g=>`<p>${esc(g.name)} · 여유 ${number(g.free_mib)} / ${number(g.total_mib)} MiB</p>`).join('')}<p>CPU 기본 ${number(n.telemetry.cpu_limit)}개 · 확인 ${esc(n.updated_at)}</p></section>`).join('')||'<p>등록된 worker가 없습니다.</p>'}</div><section class="platform-panel"><h2>선택적 고급 평가</h2><p>기본 심화 실행 0개 · 새 계획의 Boltz·Chai는 실패·재시도를 포함해 합계 최대 4회 · 기본 추천 점수 가중치 0</p>${Object.entries(optional.providers||{}).map(([name,provider])=>`<p><strong>${esc(name)}</strong> · ${provider.configured?'모델 환경 검증 필요':'모델 환경 미설정'}</p>`).join('')}<p>모델 파일과 실행 환경을 검증한 후 별도 예산으로 평가합니다. 캠페인에서 선택적 분석을 요청할 수 있습니다. 준비되지 않은 분석은 보류하고 후보 선정과 실험 인계는 계속합니다.</p></section><h2>연구 캠페인</h2><div id="platform-campaigns">${campaignList.campaigns.map(c=>`<section class="platform-panel"><strong>${esc(c.target_id)}</strong> · ${esc(c.lifecycle?.status||c.status||'계획 고정됨')}<small class="platform-identifier">${esc(c.campaign_id)}</small><button class="text-button" data-campaign="${esc(c.campaign_id)}">진행·단계 보기</button><button class="text-button" data-algorithms="${esc(c.campaign_id)}">선택적 분석</button><button class="text-button" data-campaign-pause="${esc(c.campaign_id)}">다음 단계 일시정지</button></section>`).join('')||'<p>등록된 캠페인이 없습니다. 연구 후보 비교에서 계산 단계를 확인하세요.</p>'}</div><h2>작업</h2><div class="platform-errors"></div><div class="table-wrap"><table class="platform-table"><thead><tr><th>작업</th><th>상태</th><th>노드</th><th>예산 차감 / 한도</th><th>진행 사유</th><th>관리</th></tr></thead><tbody>${result.jobs.map(j=>`<tr><td>${esc(j.request?.target_id||j.kind)}<small>${esc(j.id.slice(0,12))}</small></td><td>${esc(j.status)}</td><td>${esc(j.worker||'대기')}</td><td>${number(j.compute_seconds)} / ${number(j.budget_seconds)}초</td><td>${esc(j.progress?.reason||j.error||j.progress?.stage||'—')}</td><td><button class="text-button" data-events="${esc(j.id)}">이력</button><button class="text-button" data-result="${esc(j.id)}">결과</button>${['queued','running'].includes(j.status)?`<button class="text-button" data-cancel="${esc(j.id)}">취소</button>`:['failed','cancelled','needs_data','budget_deferred','retry_required'].includes(j.status)?`<button class="text-button" data-resume="${esc(j.id)}">재개</button>`:''}</td></tr>`).join('')}</tbody></table></div><div id="platform-job-events"></div>`;for(const action of ['cancel','resume','events','result'])for(const b of body.querySelectorAll(`[data-${action}]`))b.onclick=async()=>{try{const id=b.dataset[action];if(action==='events'||action==='result'){const events=await api(action==='events'?`/v2/jobs/${id}/events`:`/v2/jobs/${id}`);body.querySelector('#platform-job-events').innerHTML='<pre>'+esc(JSON.stringify(events,null,2))+'</pre>'}else if(action==='resume'){const job=result.jobs.find(j=>j.id===id),panel=body.querySelector('#platform-job-events'),maximum=job.budget?.maximum_seconds??28800,used=job.budget?.used_seconds??job.compute_seconds??0;if(maximum<=used){panel.innerHTML='<p class="platform-error">고정된 표적 계산 예산이 소진됐습니다. 기존 결과를 보존하고, 추가 계산은 별도 예산을 고정한 새 실행으로 요청하세요.</p>';return}panel.innerHTML=`<form id="job-resume-form" class="platform-panel"><h3>작업 재개</h3><p>공유 표적 예산의 총 한도입니다. 소진된 작업은 관리자에게 승인된 예산 증가가 필요할 수 있습니다.</p><label>총 계산 예산 (초)<input name="budget_seconds" type="number" min="1" max="${esc(maximum)}" step="any" required value="${esc(job.budget?.limit_seconds||job.budget_seconds||maximum)}"></label><button class="button" type="submit">입력 예산으로 재개 요청</button></form>`;panel.querySelector('form').onsubmit=async event=>{event.preventDefault();try{const budget=Number(event.currentTarget.elements.budget_seconds.value);if(!Number.isFinite(budget)||budget<=0)throw Error('양수의 계산 예산을 입력하세요.');await post(api,`/v2/jobs/${id}/resume`,{budget_seconds:budget});await resourcesRefresh()}catch(e){body.querySelector('.platform-errors').innerHTML=message(e)}}}else{await post(api,`/v2/jobs/${id}/${action}`,{});await resourcesRefresh()}}catch(e){body.querySelector('.platform-errors').innerHTML=message(e)}};for(const b of body.querySelectorAll('[data-campaign]'))b.onclick=async()=>{try{const result=await api('/v2/campaigns/'+b.dataset.campaign);body.querySelector('#platform-job-events').innerHTML='<pre>'+esc(JSON.stringify(result,null,2))+'</pre>'}catch(e){body.querySelector('.platform-errors').innerHTML=message(e)}};for(const b of body.querySelectorAll('[data-campaign-pause]'))b.onclick=async()=>{try{await post(api,'/v2/campaigns/'+b.dataset.campaignPause+'/pause',{});await resourcesRefresh()}catch(e){body.querySelector('.platform-errors').innerHTML=message(e)}};for(const b of body.querySelectorAll('[data-algorithms]'))b.onclick=()=>algorithmPanel(body.querySelector('#platform-job-events'),api,b.dataset.algorithms);const resourcesRefresh=()=>resourcesRender(body,api,epoch);}
const resourcesRender=resources;

async function catalog(body,api,epoch){
 const [status,snapshotList]=await Promise.all([api('/v2/catalog-status'),api('/v2/snapshots?view=summary')]);if(epoch!==state.epoch)return;
 const snapshots=snapshotList.snapshots.filter(s=>s.status==='verified');
 body.innerHTML=`<div class="platform-metrics"><div><small>등록 구조</small><strong>${number(status.compound_count)}</strong></div><div><small>DB 평가 기록 · 미지원 포함</small><strong>${number(status.published_admet_cache?.record_count??status.prediction_admitted_partitions)}</strong></div></div><p class="platform-note">카탈로그 ID·InChIKey·SMILES로 구조·공급사·기존 평가 기록을 조회합니다. 화합물 이름을 알고 있다면 <a class="inline-link" href="#discovery">새 연구 시작에서 이름을 확인하세요 →</a> DB 평가 기록 수에는 미지원·부분·실패 기록이 포함될 수 있으며, 개별 상태와 값을 함께 확인합니다. ADMET은 구조·모델·파일 검증을 통과한 파티션만 표시합니다. 판매 기록의 확인 날짜를 보고, 현재 재고는 공급사에서 확인하세요.</p><form id="platform-catalog-search" class="platform-toolbar"><label class="platform-search">구조 검색<input id="catalog-q" type="search" placeholder="정확한 카탈로그 ID, InChIKey 또는 SMILES 부분 문자열"></label><label title="피부 감작성·AMES 예측과 겹치는 독성 예측을 숨깁니다. 미평가는 포함합니다."><input type="checkbox" id="catalog-admet-risk" checked>강한 독성·피부독성 예측 숨김</label><label><input type="checkbox" id="catalog-purchase"> 공급사 재고 기록 있는 후보만</label><button class="button primary" type="submit">전체 카탈로그 검색</button></form><div id="catalog-progress" aria-live="polite"></div><div id="catalog-table"></div><div class="platform-pagination"><button class="button" id="catalog-prev" disabled>이전 50개</button><span id="catalog-page"></span><button class="button" id="catalog-next" disabled>다음 50개</button></div><section class="platform-panel"><h2>선택 구조를 표적 후보군으로 보존</h2><p>검색으로 선택했다는 사실과 실측 표적 근거를 구분합니다. 표적 근거가 없는 후보도 저장하며, 도킹은 검증된 수용체·준비형이 있을 때 실행합니다.</p><div class="platform-toolbar"><label>표적의 기준 스냅샷<select id="catalog-target"><option value="">표적 문맥을 선택하세요</option>${snapshots.map(s=>`<option value="${esc(s.snapshot_id)}">${esc(s.provenance?.marker||s.provenance?.target_id||s.snapshot_id)} · ${esc(s.provenance?.target_id||Object.keys(s.target_counts||{}).join(", "))}</option>`).join('')}</select></label><button class="button" id="catalog-snapshot">선택한 구조로 스냅샷 만들기</button><span id="catalog-selected">0개 선택</span></div><div id="catalog-snapshot-result"></div></section><div class="platform-errors"></div>`;
 let offset=0,search='',purchase=false,admetRisk=true,queryEpoch=0,rows=[],selected=new Set();
 const updateSelection=()=>body.querySelector('#catalog-selected').textContent=`${number(selected.size)}개 선택`;
 const query=async()=>{
  const generation=++queryEpoch;body.querySelector('#catalog-progress').textContent='전체 카탈로그에서 검색 중입니다…';
  const captured={q:search,purchasable_only:purchase,hide_severe_admet:admetRisk,limit:50,offset};
  let result=await post(api,'/v2/catalog-queries',captured);
  while(result.status==='running'&&epoch===state.epoch&&generation===queryEpoch){body.querySelector('#catalog-progress').textContent=`검색 진행 중 · ${number(result.elapsed_seconds)}초 · 완료된 행을 기다리고 있습니다.`;await new Promise(resolve=>setTimeout(resolve,1200));if(epoch!==state.epoch||generation!==queryEpoch)return;result=await api('/v2/catalog-queries/'+encodeURIComponent(result.query_id))}
  if(epoch!==state.epoch||generation!==queryEpoch)return;
  if(result.status!=='complete')throw Error(result.error||'카탈로그 검색이 완료되지 않았습니다.');
  rows=result.rows;body.querySelector('#catalog-progress').textContent=`검색 완료 · ${number(result.elapsed_seconds)}초 · 전체 구조에서 ${rows.length}행 조회`;
  body.querySelector('#catalog-table').innerHTML=`<div class="table-wrap"><table class="platform-table"><thead><tr><th><input type="checkbox" id="catalog-select-page" aria-label="현재 페이지 선택"></th><th>카탈로그 ID</th><th>InChIKey</th><th>구조 SMILES</th><th>상세</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td><input type="checkbox" data-catalog-select="${i}" ${selected.has(r.compound_id)?'checked':''} aria-label="${esc(r.compound_id)} 선택"></td><td class="platform-identifier">${esc(r.compound_id)}</td><td>${esc(r.inchikey)}</td><td class="platform-structure-text">${esc(r.identity_smiles)}</td><td><button class="text-button" data-catalog-detail="${i}">공급·실험·예측</button></td></tr>`).join('')||'<tr><td colspan="5">일치하는 구조가 없습니다.</td></tr>'}</tbody></table></div>`;
  body.querySelector('#catalog-page').textContent=rows.length?`${offset+1}–${offset+rows.length}`:'0';body.querySelector('#catalog-prev').disabled=offset===0;body.querySelector('#catalog-next').disabled=rows.length<50||offset>=99950;
  for(const checkbox of body.querySelectorAll('[data-catalog-select]'))checkbox.onchange=()=>{const id=rows[Number(checkbox.dataset.catalogSelect)].compound_id;if(checkbox.checked)selected.add(id);else selected.delete(id);updateSelection()};
  body.querySelector('#catalog-select-page').onchange=e=>{for(const checkbox of body.querySelectorAll('[data-catalog-select]')){checkbox.checked=e.target.checked;checkbox.onchange()}};
  for(const button of body.querySelectorAll('[data-catalog-detail]'))button.onclick=async()=>{try{button.disabled=true;const detail=await api('/v2/catalog-candidates/'+encodeURIComponent(rows[Number(button.dataset.catalogDetail)].compound_id));const dialog=document.querySelector('#detail-dialog'),content=document.querySelector('#detail-content');content.innerHTML=`<div class="platform-detail"><button class="icon-button" id="catalog-detail-close" aria-label="상세 닫기">×</button><h2 id="detail-title">구조·공급·실험 근거</h2><p class="platform-identifier">${esc(detail.compound?.compound_id)}</p><p>검증되지 않은 예측은 미평가로 남깁니다. 공급 기록과 실험 자료의 원 출처·날짜를 확인하세요.</p><h3>공급 정보</h3>${(detail.offers||[]).map(o=>{const link=safeLink(o.url||o.source_url||o.product_url||o.purchase_route);return `<p>${esc(o.vendor||o.supplier||o.source||'공급사')} · ${esc(o.availability||'재고 미확인')} · ${esc(o.checked_at||o.retrieved_at||o.source_date||o.evidence_date||'확인 날짜 미기록')} ${link?`<a href="${esc(link)}" target="_blank" rel="noopener noreferrer">원문 보기</a>`:''}</p>`}).join('')||'<p>공급 정보 미기록</p>'}<h3>전체 기록</h3><pre>${esc(JSON.stringify(detail,null,2))}</pre></div>`;content.querySelector('#catalog-detail-close').onclick=()=>dialog.close();if(!dialog.open)dialog.showModal()}catch(error){body.querySelector('.platform-errors').innerHTML=message(error)}finally{button.disabled=false}};
 };
 listen(body,'#platform-catalog-search','submit',async e=>{e.preventDefault();search=body.querySelector('#catalog-q').value.trim();purchase=body.querySelector('#catalog-purchase').checked;admetRisk=body.querySelector('#catalog-admet-risk').checked;offset=0;selected.clear();updateSelection();await query()});
 listen(body,'#catalog-prev','click',async()=>{offset=Math.max(0,offset-50);await query()});
 listen(body,'#catalog-next','click',async()=>{offset+=50;await query()});
 listen(body,'#catalog-snapshot','click',async e=>{if(!selected.size)throw Error('구조를 먼저 선택해 주세요.');const targetSnapshot=snapshots.find(s=>s.snapshot_id===body.querySelector('#catalog-target').value);if(!targetSnapshot)throw Error('표적의 기준 스냅샷을 선택해 주세요.');const target=targetSnapshot.provenance?.target_id||Object.keys(targetSnapshot.target_counts)[0];e.target.disabled=true;try{let result=await post(api,'/v2/catalog-snapshots',{compound_ids:[...selected],target_snapshot_id:targetSnapshot.snapshot_id,target_id:target});while(result.status==='running'&&epoch===state.epoch){body.querySelector('#catalog-snapshot-result').textContent='선택한 구조와 공급·실험 근거를 고정하고 있습니다…';await new Promise(resolve=>setTimeout(resolve,1500));result=await api('/v2/catalog-snapshots/'+encodeURIComponent(result.materialization_id))}if(epoch!==state.epoch)return;if(result.status!=='complete')throw Error(result.error||'스냅샷 생성이 완료되지 않았습니다.');const manifest=result.snapshot;state.snapshot=manifest.snapshot_id;state.target=manifest.provenance?.target_id||target;body.querySelector('#catalog-snapshot-result').innerHTML=`<p>${number(manifest.candidate_count)}개 구조를 보존했습니다.</p><a class="button primary" href="#research">연구 후보 비교에서 보기</a>`}finally{e.target.disabled=false}});
}

async function campaignPanel(root,api,context){
 root.innerHTML=`<section class="platform-panel"><h2>표적 계산 단계</h2><p>최대 1,000개 도킹 → 최대 96개·시드 1회 재확인 → 최대 16개·추가 수용체 1개 검토를 같은 표적 예산 안에서 진행합니다. 기본 예산은 실제 계산 8시간이며 심화 계산은 자동 실행하지 않습니다.</p><p>수용체와 준비형이 검증되지 않아도 후보 탐색과 실험 배치 작성은 계속할 수 있습니다.</p><div class="platform-toolbar"><label>검증된 준비 입력 ID (선택)<input id="campaign-input-id" placeholder="등록한 입력 ID"></label><button class="button" id="campaign-plan-refresh">실행 가능 단계 확인</button><button class="button primary" id="campaign-freeze">계획·입력 고정</button></div><details><summary>준비 자료 등록</summary><p>원래 SkinPipe 준비 영수증·수용체 식별 카드·구조 파일을 등록합니다. 내용 해시와 표적·화합물 정체성을 서버가 다시 검증합니다.</p><label>자료 파일 선택<input id="campaign-artifacts" type="file" multiple></label><div id="campaign-artifact-results"></div><label>입력 매니페스트 SHA256<input id="campaign-manifest-sha" placeholder="skinpipe-campaign-inputs-v1 JSON 자료 해시"></label><button class="button" id="campaign-register">준비 자료 검증·등록</button></details><div class="platform-errors"></div><div id="campaign-plan-result"></div><div id="campaign-run-result"></div></section>`;
 const input=()=>({ ...context,...(root.querySelector('#campaign-input-id').value.trim()?{input_id:root.querySelector('#campaign-input-id').value.trim()}:{})});
 const refresh=async()=>{const plan=await post(api,'/v2/plans',input());root.querySelector('#campaign-plan-result').innerHTML=`<h3>계산 계획과 보류 사유</h3><p>계획을 확인한 뒤 실행을 시작하세요.</p><pre>${esc(JSON.stringify(plan,null,2))}</pre>`;return plan};
 listen(root,'#campaign-plan-refresh','click',refresh);
 listen(root,'#campaign-artifacts','change',async e=>{const receipts=[];for(const file of e.target.files){const raw=await file.arrayBuffer();if(raw.byteLength>8*1024*1024)throw Error('자료는 파일당 8 MiB 이하여야 합니다.');const sha=[...new Uint8Array(await crypto.subtle.digest('SHA-256',raw))].map(v=>v.toString(16).padStart(2,'0')).join('');const receipt=await post(api,'/v2/campaign-inputs/artifacts',{name:file.name,sha256:sha,media_type:file.type||'application/octet-stream',base64:await toBase64(file)});receipts.push({name:file.name,...receipt});root.querySelector('#campaign-artifact-results').innerHTML='<pre>'+esc(JSON.stringify(receipts,null,2))+'</pre>'}});
 listen(root,'#campaign-register','click',async e=>{e.target.disabled=true;try{const registered=await post(api,'/v2/campaign-inputs',{manifest_sha256:root.querySelector('#campaign-manifest-sha').value.trim()});root.querySelector('#campaign-input-id').value=registered.input_id;await refresh()}finally{e.target.disabled=false}});
 listen(root,'#campaign-freeze','click',async e=>{e.target.disabled=true;try{const result=await post(api,'/v2/campaigns',input());const output=root.querySelector('#campaign-run-result');output.innerHTML=`<h3>고정된 연구 캠페인</h3><p>${esc(result.campaign_id)}</p><button class="button primary" id="campaign-run">기본 예산으로 실행·재개</button><a class="button" href="#resources">진행 상황 보기</a><pre>${esc(JSON.stringify(result,null,2))}</pre>`;listen(output,'#campaign-run','click',async b=>{b.target.disabled=true;try{const started=await post(api,'/v2/campaigns/'+result.campaign_id+'/run',{});output.innerHTML=`<p>실행 상태: ${esc(started.status||started.campaign?.lifecycle?.status||'접수됨')}</p><a class="button primary" href="#resources">작업·자원 확인</a><pre>${esc(JSON.stringify(started,null,2))}</pre>`}catch(error){b.target.disabled=false;throw error}})}finally{e.target.disabled=false}});
 await refresh();
}

async function algorithmPanel(root,api,campaignId){
 try{
  const available=await api('/v2/algorithms');
  const names={fpsim2:'빠른 유사체 검색',cdpl:'3D 형태·약리 특징 비교',dimorphite:'양성자화·토토머 검토',posebusters:'포즈 타당성 검토',prolif:'상호작용 설명',fpocket:'포켓 탐색 · fpocket',p2rank:'포켓 탐색 · P2Rank',gnina:'GNINA 재평가',boltzina:'Boltzina 친화도 재평가',boltz2:'Boltz 구조·친화도 모델',chai1:'Chai 구조 모델',openadmet:'OpenADMET 예측',chemeleon:'학습된 CheMeleon 예측',unidock2:'Uni-Dock2 비교 검증'};
  root.innerHTML=`<section class="platform-panel"><h3>선택적 분석</h3><p>구매 근거가 있는 고유 후보를 정해진 규모 안에서 선택합니다. 결과는 별도로 기록하며 기본 추천 점수에 자동 합산하지 않습니다. 모델 환경과 실제 입력 검증이 부족하면 해당 분석을 보류합니다.</p><label>분석 방법 <select id="algorithm-provider">${available.providers.filter(p=>p!=='openfe').map(p=>`<option value="${esc(p)}">${esc(names[p]||p)}</option>`).join('')}</select></label><button class="button" id="algorithm-submit">분석 요청</button><div id="algorithm-result"></div></section>`;
  listen(root,'#algorithm-submit','click',async e=>{
   e.target.disabled=true;
   try{
    const result=await post(api,'/v2/campaigns/'+encodeURIComponent(campaignId)+'/algorithm-jobs',{provider:root.querySelector('#algorithm-provider').value});
    root.querySelector('#algorithm-result').innerHTML=`<p>${result.status==='submitted'?'접수됨 · 작업 화면에서 진행과 결과를 확인하세요.':'보류됨 · 입력 또는 실행 환경을 확인하세요.'}</p><pre>${esc(JSON.stringify(result,null,2))}</pre>`;
   }finally{e.target.disabled=false}
  });
 }catch(e){root.innerHTML=message(e)}
}
